    -- Calculate III from linked investigation details
    SELECT (0.6 * id.behansc + 0.4 * id.netansc) INTO v_iii
    FROM investigationdetails id
    WHERE id.invdetreg = NEW.invdetref;

    -- If III > 75, prevent resolution
    IF v_iii > 75 THEN
      RAISE EXCEPTION 'Resolution blocked: Investigation Intensity Index exceeds threshold. Current III: %', v_iii;
    END IF;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_check_resolution
BEFORE UPDATE ON enforcementactions
FOR EACH ROW
WHEN (NEW.resstat = 'Resolved')
EXECUTE FUNCTION check_resolution_risk();

